async function download(p,call,id){const task=p.waitForEvent('download');await p.evaluate(({call,id})=>globalThis[call](id),{call,id});const d=await task,stream=await d.createReadStream(),chunks=[];for await(const c of stream)chunks.push(c);return {file:d.suggestedFilename(),text:Buffer.concat(chunks).toString()}}
