 await check('57 delivery provenance and explicit supply rewards remain single and local',async({page:p})=>{
  const cases=[];
  for(const originCity of [0,null,1]){
   await create(p,'Lieferherkunft '+originCity);assert(await p.evaluate(()=>acceptPoliticalJob('supply')));const job=(await state(p)).politics.jobs[0];
   await prep(p,()=>safetyRun(()=>{const q=s.politics.jobs[0],v=ship();v.cargo[q.good]=q.n;v.costs[q.good]=8;v.bookCosts??={};v.origins??={};v.bookCosts[q.good]=8;v.origins[q.good]=[{city:0,n:q.n}];s.quests=[{j:q.good,n:q.n,reward:100,until:totalDay()+10,city:s.city}];save()}));
   await p.evaluate(originCity=>safetyRun(()=>{const q=s.politics.jobs[0];ship().origins[q.good][0].city=originCity;save()}),originCity);const before=await state(p);await p.evaluate(()=>marketView());await p.locator('#qty'+job.good).fill(String(job.n));await p.evaluate(j=>trade(j,-1),job.good);const after=await state(p),eligible=originCity===1;assert.equal(after.gold,before.gold+job.n*before.markets[0][job.good].price+(eligible?100:0));assert.equal(after.completed,before.completed+Number(eligible));assert.equal(after.politics.records.length,Number(eligible));assert.equal(after.rep,before.rep+(eligible?4:0));
   if(eligible){await p.locator('#qty'+job.good).fill(String(job.n));await p.evaluate(j=>trade(j,-1),job.good);const again=await state(p);assert.equal(again.gold,after.gold);assert.deepEqual(again.politics.records,after.politics.records);assert.equal(again.completed,after.completed)}cases.push({originCity,deliveryReward:eligible?100:0,politicalReceipts:Number(eligible)});
  }
  return {cases,noSameCityOrUnknownOriginReward:true,noDoubleReward:true};
 });
